<?php /** Session attendance/lesson statistics. */ ?>
<div class="lms-card"><div class="lms-card-header"><i class="fa-solid fa-calendar-check me-1"></i>Thống kê số buổi học</div><div class="lms-card-body">
<form method="get" action="<?= e(lms_url($alias)) ?>" class="row g-2 align-items-end mb-3"><div class="col-md-3"><label class="form-label">Mã học viên</label><input name="student_code" class="form-control" value="<?= e($studentCode) ?>" placeholder="Master227"></div><div class="col-md-3"><label class="form-label">Từ ngày</label><input type="date" name="date_from" class="form-control" value="<?= e($dateFrom) ?>"></div><div class="col-md-3"><label class="form-label">Đến ngày</label><input type="date" name="date_to" class="form-control" value="<?= e($dateTo) ?>"></div><div class="col-md-3"><button class="btn btn-primary"><i class="fa-solid fa-magnifying-glass me-1"></i>Tìm</button><?php if($student): ?> <a class="btn btn-success" href="<?= e(lms_url($alias,'xuat',array('student_code'=>$studentCode,'date_from'=>$dateFrom,'date_to'=>$dateTo))) ?>"><i class="fa-solid fa-file-csv me-1"></i>Xuất CSV</a><?php endif; ?></div></form>
